func fxtRaw(v int64) int32 {
	// An Fx as its raw count of 1/65536 units, when that fits an I32.
	return int32(v)
}

func TestIntegersAndRealsBecomeFx(emonT *testing.T) {
	port.AssertEq(emonT, fxtRaw(fx.FxOfInt(3)), 196608, "3 is 3*65536")
	port.AssertEq(emonT, fxtRaw(fx.FxOfInt(-2)), -131072, "-2")
	port.AssertEq(emonT, fxtRaw(fx.FxOfReal(5, 1)), 32768, "0.5 is 32768")
	port.AssertEq(emonT, fxtRaw(fx.FxOfReal(25, 2)), 16384, "0.25")
	port.AssertEq(emonT, fxtRaw(fx.FxOfReal(-75, 2)), -49152, "-0.75")
	port.AssertEq(emonT, fxtRaw(fx.FxOfReal(1, 5)), 1, "0.00001 rounds to 1 unit (0.655)")
	port.AssertEq(emonT, fxtRaw(fx.FxOfReal(1, 6)), 0, "0.000001 is under half a unit")
	port.AssertEq(emonT, fxtRaw(fx.FxOfReal(1234567, 3)), 80908583, "1234.567 is 80908583 units")
	port.AssertEq(emonT, fx.FxRound(fx.FxOfReal(149, 2)), 1, "1.49 rounds to 1")
	port.AssertEq(emonT, fx.FxRound(fx.FxOfReal(150, 2)), 2, "1.50 rounds up")
	port.AssertEq(emonT, fx.FxRound(fx.FxOfReal(-150, 2)), -1, "-1.50 rounds up, toward positive")
	port.AssertEq(emonT, fx.FxRound(fx.FxOfReal(-151, 2)), -2, "-1.51")
	port.AssertEq(emonT, fx.FxFloor(fx.FxOfReal(-1, 1)), -1, "floor of -0.1 is -1")
	port.AssertEq(emonT, fx.FxFloor(fx.FxOfReal(19, 1)), 1, "floor of 1.9")
}

func TestMultiplicationAndDivisionRoundHalfAwayFromZero(emonT *testing.T) {
	port.AssertEq(emonT, fxtRaw(fx.FxMul(fx.FxOfInt(3), fx.FxOfInt(4))), 786432, "3*4")
	port.AssertEq(emonT, fxtRaw(fx.FxMul(fx.FxOfReal(5, 1), fx.FxOfReal(5, 1))), 16384, "0.5*0.5")
	port.AssertEq(emonT, fxtRaw(fx.FxMul(fx.FxOfInt(-3), fx.FxOfReal(5, 1))), -98304, "-3*0.5")
	port.AssertEq(emonT, fxtRaw(fx.FxMul(int64(1), int64(32768))), 1, "half a unit rounds away: 1")
	port.AssertEq(emonT, fxtRaw(fx.FxMul(int64(-1), int64(32768))), -1, "and -1")
	port.AssertEq(emonT, fxtRaw(fx.FxMul(int64(1), int64(32767))), 0, "under half: 0")
	port.AssertEq(emonT, fxtRaw(fx.FxDiv(fx.FxOfInt(1), fx.FxOfInt(4))), 16384, "1/4")
	port.AssertEq(emonT, fxtRaw(fx.FxDiv(fx.FxOfInt(10), fx.FxOfInt(-4))), -163840, "10/-4")
	port.AssertEq(emonT, fxtRaw(fx.FxDiv(fx.FxOfInt(1), int64(0))), 0, "division by zero is 0, not a fault")
	port.AssertEq(emonT, fxtRaw(fx.FxMuldiv(int64(27783), fx.FxOfInt(12), int64(100000))), 218494, "a glyph width: 277.83/1000 em at 12 is 3.334")
	port.AssertEq(emonT, fxtRaw(fx.FxMuldiv(int64(-7), int64(1), int64(2))), -4, "-3.5 rounds away")
	port.AssertEq(emonT, fxtRaw(fx.FxMuldiv(int64(7), int64(1), int64(-2))), -4, "3.5 over -1 ... away")
	port.AssertEq(emonT, fxtRaw(fx.FxMuldiv(int64(-7), int64(1), int64(-2))), 4, "positive again")
}

func TestHostileMagnitudesWrapAndClampButNeverFault(emonT *testing.T) {
	port.AssertEq(emonT, fx.FxRound(fx.FxClamp(fx.FxOfInt(2147483647))), 268435456, "a huge integer is clamped to 2^28")
	port.AssertThat(emonT, fx.FxClamp(int64(9000000000000000)) == int64(17592186044416), "clamped above")
	port.AssertThat(emonT, fx.FxClamp(int64(-9000000000000000)) == int64(-17592186044416), "clamped below")
	port.AssertEq(emonT, fx.FxRound(fx.FxOfInt(2147483647)), 2147483647, "the largest integer")
	port.AssertEq(emonT, fx.FxRound(fx.FxOfInt(2147483647)), 2147483647, "saturation in the round")
}

func TestSquareRootsAndLengths(emonT *testing.T) {
	port.AssertEq(emonT, int32(fx.FxIsqrt(int64(0))), 0, "isqrt 0")
	port.AssertEq(emonT, int32(fx.FxIsqrt(int64(1))), 1, "isqrt 1")
	port.AssertEq(emonT, int32(fx.FxIsqrt(int64(15))), 3, "isqrt 15")
	port.AssertEq(emonT, int32(fx.FxIsqrt(int64(16))), 4, "isqrt 16")
	port.AssertEq(emonT, int32(fx.FxIsqrt(int64(2147395600))), 46340, "isqrt of 46340^2")
	port.AssertEq(emonT, fxtRaw(fx.FxSqrt(fx.FxOfInt(4))), 131072, "sqrt 4 = 2")
	port.AssertEq(emonT, fxtRaw(fx.FxSqrt(fx.FxOfInt(2))), 92681, "sqrt 2 = 1.41421 (floor of 92681.9)")
	port.AssertEq(emonT, fxtRaw(fx.FxSqrt(int64(-5))), 0, "sqrt of a negative is 0")
	port.AssertEq(emonT, fx.FxRound(fx.FxHypot(fx.FxOfInt(3), fx.FxOfInt(4))), 5, "3-4-5")
	port.AssertEq(emonT, fx.FxRound(fx.FxHypot(fx.FxOfInt(-3), fx.FxOfInt(4))), 5, "signs do not matter")
	port.AssertEq(emonT, fx.FxRound(fx.FxHypot(fx.FxOfInt(0), fx.FxOfInt(0))), 0, "the zero vector")
	port.AssertEq(emonT, fx.FxRound(fx.FxHypot(fx.FxOfInt(1000000), fx.FxOfInt(1000000))), 1414214, "large vectors keep nine digits")
}

func TestAtan2IsExactOnTheAxesAndCloseBetween(emonT *testing.T) {
	port.AssertEq(emonT, fx.FxAtan2(int64(0), fx.FxOfInt(1)), 0, "east")
	port.AssertEq(emonT, fx.FxAtan2(fx.FxOfInt(1), int64(0)), 9000, "north")
	port.AssertEq(emonT, fx.FxAtan2(int64(0), fx.FxOfInt(-1)), 18000, "west")
	port.AssertEq(emonT, fx.FxAtan2(fx.FxOfInt(-1), int64(0)), 27000, "south")
	port.AssertEq(emonT, fx.FxAtan2(int64(0), int64(0)), 0, "the zero vector")
	port.AssertEq(emonT, fx.FxAtan2(fx.FxOfInt(1), fx.FxOfInt(1)), 4500, "45")
	port.AssertEq(emonT, fx.FxAtan2(fx.FxOfInt(1), fx.FxOfInt(-1)), 13500, "135")
	port.AssertEq(emonT, fx.FxAtan2(fx.FxOfInt(-1), fx.FxOfInt(-1)), 22500, "225")
	port.AssertEq(emonT, fx.FxAtan2(fx.FxOfInt(-1), fx.FxOfInt(1)), 31500, "315")
	port.AssertEq(emonT, fx.FxAtan2(fx.FxOfInt(1), fx.FxOfInt(2)), 2656, "atan(0.5) = 26.565 degrees (CORDIC: within a centi-degree)")
	port.AssertEq(emonT, fx.FxAtan2(fx.FxOfInt(3), fx.FxOfInt(4)), 3687, "atan(3/4) = 36.87 degrees")
	port.AssertEq(emonT, fx.FxAtan2(fx.FxOfInt(1), fx.FxOfInt(100)), 57, "atan(0.01) = 0.573 degrees")
	port.AssertEq(emonT, fx.FxAtan2(int64(1), fx.FxOfInt(100)), 0, "a hair above east is still 0")
	port.AssertEq(emonT, fx.FxAtan2(fx.FxOfInt(-1), fx.FxOfInt(100)), 35943, "a hair below east wraps to 359.43")
	port.AssertEq(emonT, fx.FxAtan2(int64(1099511627776), int64(1099511627776)), 4500, "huge vectors are normalised")
	port.AssertEq(emonT, fx.FxAtan2(int64(3), int64(4)), 3687, "tiny vectors are normalised")
}

func TestAnFxIsTwoCells(emonT *testing.T) {
	var c *port.Cells = port.NewCells()
	var big int64 = int64(98765432109)
	var neg int64 = int64(-98765432109)
	port.AssertEq(emonT, fx.FxPush(c, big), 0, "first at 0")
	port.AssertEq(emonT, fx.FxPush(c, neg), 2, "second at 2")
	port.AssertEq(emonT, port.CellsLen(c), 4, "four cells")
	port.AssertThat(emonT, fx.FxGet(c, 0) == big, "a positive value above 2^32 survives")
	port.AssertThat(emonT, fx.FxGet(c, 2) == neg, "and a negative one")
	fx.FxPut(c, 0, int64(-1))
	port.AssertThat(emonT, fx.FxGet(c, 0) == int64(-1), "minus one (all ones in the low half)")
	fx.FxPut(c, 0, int64(2147483648))
	port.AssertThat(emonT, fx.FxGet(c, 0) == int64(2147483648), "2^31: the low half's sign bit is not a sign")
	port.AssertThat(emonT, fx.FxJoin(0, -1) == int64(4294967295), "join reads the low half unsigned")
}

func TestMatricesComposeInPdfOrder(emonT *testing.T) {
	var c *port.Cells = port.NewCells()
	var i int32 = 0
	for i < 48 {
		fx.FxPush(c, int64(0))
		i += 2
	}
	// 0: translate (10, 20); 12: scale 2 by 3; 24: result
	fx.MxTranslate(c, 0, fx.FxOfInt(10), fx.FxOfInt(20))
	fx.MxSet(c, 12, fx.FxOfInt(2), int64(0), int64(0), fx.FxOfInt(3), int64(0), int64(0))
	// translate then scale: (1,1) -> (11,21) -> (22,63)
	fx.MxMul(c, 24, 0, 12)
	port.AssertEq(emonT, fx.FxRound(fx.MxX(c, 24, fx.FxOfInt(1), fx.FxOfInt(1))), 22, "x")
	port.AssertEq(emonT, fx.FxRound(fx.MxY(c, 24, fx.FxOfInt(1), fx.FxOfInt(1))), 63, "y")
	// scale then translate: (1,1) -> (2,3) -> (12,23)
	fx.MxMul(c, 24, 12, 0)
	port.AssertEq(emonT, fx.FxRound(fx.MxX(c, 24, fx.FxOfInt(1), fx.FxOfInt(1))), 12, "x, other order")
	port.AssertEq(emonT, fx.FxRound(fx.MxY(c, 24, fx.FxOfInt(1), fx.FxOfInt(1))), 23, "y, other order")
	// a product written over an operand
	fx.MxMul(c, 12, 12, 0)
	port.AssertEq(emonT, fx.FxRound(fx.MxX(c, 12, fx.FxOfInt(1), fx.FxOfInt(1))), 12, "dst is x")
	fx.MxIdent(c, 36)
	fx.MxMul(c, 36, 36, 36)
	port.AssertEq(emonT, fx.FxRound(fx.MxX(c, 36, fx.FxOfInt(7), fx.FxOfInt(9))), 7, "the identity squared")
	port.AssertEq(emonT, fx.FxRound(fx.MxY(c, 36, fx.FxOfInt(7), fx.FxOfInt(9))), 9, "is the identity")
}

func TestARotationBy90TurnsTheAxes(emonT *testing.T) {
	var c *port.Cells = port.NewCells()
	var i int32 = 0
	for i < 24 {
		fx.FxPush(c, int64(0))
		i += 2
	}
	// [0 1 -1 0 0 0]: x axis to y, y axis to -x
	fx.MxSet(c, 0, int64(0), fx.FxOfInt(1), fx.FxOfInt(-1), int64(0), int64(0), int64(0))
	port.AssertEq(emonT, fx.FxRound(fx.MxX(c, 0, fx.FxOfInt(1), int64(0))), 0, "(1,0) x")
	port.AssertEq(emonT, fx.FxRound(fx.MxY(c, 0, fx.FxOfInt(1), int64(0))), 1, "(1,0) y")
	port.AssertEq(emonT, fx.FxRound(fx.MxX(c, 0, int64(0), fx.FxOfInt(1))), -1, "(0,1) x")
	fx.MxCopy(c, 12, 0)
	fx.MxMul(c, 12, 12, 0)
	port.AssertEq(emonT, fx.FxRound(fx.MxX(c, 12, fx.FxOfInt(1), int64(0))), -1, "twice is 180 degrees")
}

func fxtDist(v int64, want int32) int32 {
	// |v - want| in raw Fx units.
	var d int32 = int32(v) - want
	if d < 0 {
		return 0 - d
	}
	return d
}

func TestSineAndCosineAreExactAtTheAxesAndCloseBetween(emonT *testing.T) {
	port.AssertEq(emonT, fxtRaw(fx.FxCos(0)), 65536, "cos 0")
	port.AssertEq(emonT, fxtRaw(fx.FxSin(0)), 0, "sin 0")
	port.AssertEq(emonT, fxtRaw(fx.FxCos(9000)), 0, "cos 90")
	port.AssertEq(emonT, fxtRaw(fx.FxSin(9000)), 65536, "sin 90")
	port.AssertEq(emonT, fxtRaw(fx.FxCos(18000)), -65536, "cos 180")
	port.AssertEq(emonT, fxtRaw(fx.FxSin(18000)), 0, "sin 180")
	port.AssertEq(emonT, fxtRaw(fx.FxCos(27000)), 0, "cos 270")
	port.AssertEq(emonT, fxtRaw(fx.FxSin(27000)), -65536, "sin 270")
	port.AssertThat(emonT, fxtDist(fx.FxSin(4500), 46341) <= 2, "sin 45 = 0.70711")
	port.AssertThat(emonT, fxtDist(fx.FxCos(4500), 46341) <= 2, "cos 45")
	port.AssertThat(emonT, fxtDist(fx.FxSin(3000), 32768) <= 2, "sin 30 = 0.5")
	port.AssertThat(emonT, fxtDist(fx.FxCos(6000), 32768) <= 2, "cos 60 = 0.5")
	port.AssertThat(emonT, fxtDist(fx.FxCos(13500), -46341) <= 2, "cos 135")
	port.AssertThat(emonT, fxtDist(fx.FxSin(31500), -46341) <= 2, "sin 315")
	port.AssertThat(emonT, fxtDist(fx.FxSin(-4500), -46341) <= 2, "a negative angle")
	port.AssertThat(emonT, fxtDist(fx.FxCos(40500), 46341) <= 2, "an angle past a turn")
}
